import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Element_hasClass_TriageGen2Test {

    private Tag tag;
    private Attributes attributes;
    private Element element;

    @Before
    public void setUp() {
        tag = new Tag("div");
        attributes = new Attributes();
        element = new Element(tag, "http://example.com", attributes);
    }

    @Test
    public void testEmptyClassAttribute() {
        assertFalse(element.hasClass("test"));
    }

    @Test
    public void testExactMatch() {
        attributes.put("class", "test");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testCaseInsensitiveExactMatch() {
        attributes.put("class", "Test");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testNoMatch() {
        attributes.put("class", "example");
        element = new Element(tag, "http://example.com", attributes);
        assertFalse(element.hasClass("test"));
    }

    @Test
    public void testMultipleClassesNoMatch() {
        attributes.put("class", "example test2");
        element = new Element(tag, "http://example.com", attributes);
        assertFalse(element.hasClass("test"));
    }

    @Test
    public void testMultipleClassesMatch() {
        attributes.put("class", "example test test2");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testLeadingWhitespace() {
        attributes.put("class", " test");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testTrailingWhitespace() {
        attributes.put("class", "test ");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testSurroundedByWhitespace() {
        attributes.put("class", " test ");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testClassWithUnderscore() {
        attributes.put("class", "my_test");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("my_test"));
    }

    @Test
    public void testClassWithMixedCase() {
        attributes.put("class", "My_Test");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("my_test"));
    }

    @Test
    public void testEmptyClassName() {
        assertFalse(element.hasClass(""));
    }

    @Test
    public void testNullClassName() {
        assertFalse(element.hasClass(null));
    }

    @Test
    public void testClassWithMultipleUnderscores() {
        attributes.put("class", "test_example");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test_example"));
    }

    @Test
    public void testClassWithSpecialCharacters() {
        attributes.put("class", "test@example.com");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test@example.com"));
    }

    @Test
    public void testClassWithNumericalValues() {
        attributes.put("class", "test123");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test123"));
    }

    @Test
    public void testClassWithPunctuation() {
        attributes.put("class", "test!");
        element = new Element(tag, "http://example.com", attributes);
        assertTrue(element.hasClass("test!"));
    }
}
